[
  {
    "id": "task-1",
    "title": "设计HTML结构与基础布局",
    "description": "编写单页HTML文件的基础骨架。包含：一个输入区域（日期时间选择器input[type='datetime-local']与启动按钮），一个倒计时显示区域（四个独立的数字区块，分别显示天、时、分、秒），以及一个自定义模态弹窗容器（默认隐藏）。所有元素使用语义化标签，并分配唯一ID供JS操作。文件命名为countdown.html。",
    "dependencies": [],
    "required_capability": "code"
  },
  {
    "id": "task-2",
    "title": "实现深色霓虹科技风CSS样式",
    "description": "为countdown.html编写完整CSS样式。要求：深色背景（#0a0a0a或类似），霓虹发光效果使用text-shadow和box-shadow（青色/品红色调），倒计时数字使用大号字体并带发光边框，输入框和按钮采用深色半透明背景+霓虹边框，自定义模态弹窗居中显示并带有模糊背景遮罩。所有样式写在文件内部<style>中。",
    "dependencies": ["task-1"],
    "required_capability": "code"
  },
  {
    "id": "task-3",
    "title": "编写倒计时核心逻辑与交互",
    "description": "在countdown.html中编写JavaScript逻辑。功能：1) 用户点击启动按钮后，读取datetime-local输入值并校验是否合法且为未来时间；2) 使用setInterval每秒计算剩余时间（天/时/分/秒），更新到对应DOM元素；3) 当剩余时间归零时，停止定时器，显示自定义模态弹窗（内容为“倒计时结束！”），弹窗带有关闭按钮；4) 用户可重新输入新时间并再次启动。所有脚本写在文件内部<script>中。",
    "dependencies": ["task-1", "task-2"],
    "required_capability": "code"
  },
  {
    "id": "task-4",
    "title": "验证倒计时功能与视觉表现",
    "description": "打开countdown.html在浏览器中执行以下验证：1) 输入一个未来5分钟后的时间，点击启动，确认倒计时数字正确递减且每秒更新；2) 测试输入过去时间或空值，应弹出提示且不启动倒计时；3) 等待倒计时归零或手动设置一个很近的时间，确认弹窗出现且倒计时停止；4) 确认深色霓虹样式在所有数字和交互元素上正确渲染，无布局错位。记录验证结果。",
    "dependencies": ["task-3"],
    "required_capability": "verify"
  }
]
